-- 110 clients (particuliers, professionnels, entreprises, administrations)
-- Données réelles fournies par l'utilisateur
-- Complément pour atteindre 110 clients (60 supplémentaires avec generate_series)
SELECT
    'Client' || generate_series,
    'Nom' || generate_series,
    CASE WHEN generate_series % 3 = 0 THEN 'Entreprise ' || generate_series ELSE NULL END,
    'client' || generate_series || '@example.com',
    '012345678' || LPAD(generate_series::text, 2, '0'),
    'Adresse ' || generate_series,
    'Ville ' || generate_series,
    'Belgique',
    '1' || LPAD(generate_series::text, 3, '0'),
    CASE WHEN generate_series % 3 = 0 THEN 'ENTREPRISE' ELSE 'PARTICULIER' END
FROM generate_series(51, 110);